"""Generate immutable scalar lookup tables from the bundled Unicode 17 data."""
from pathlib import Path
import re, hashlib, json
base=Path(__file__).resolve().parent
repo=base.parents[1]
out=repo/'src/WebApi.Infrastructure/Contracts/IdnaUnicodeData.cs'
classes=['L','R','AL','AN','EN','ES','CS','ET','ON','BN','NSM','Other']
aliases={'Left_To_Right':'L','Right_To_Left':'R','Arabic_Letter':'AL','European_Terminator':'ET'}
values=['L']*0x110000
bidi=(base/'17.0.0/DerivedBidiClass.txt').read_text()
for line in bidi.splitlines():
 m=re.match(r'# @missing:\s*([0-9A-F.]+);\s*(\w+)',line)
 if m:
  span,name=m.groups();start,*end=span.split('..');a=int(start,16);b=int(end[0],16) if end else a
  values[a:b+1]=[aliases.get(name,name)]*(b-a+1)
for line in bidi.splitlines():
 m=re.match(r'([0-9A-F.]+)\s*;\s*(\w+)',line)
 if m:
  span,name=m.groups();start,*end=span.split('..');a=int(start,16);b=int(end[0],16) if end else a
  values[a:b+1]=[name if name in classes else 'Other']*(b-a+1)
def ranges(values):
 start=0
 for i in range(1,len(values)+1):
  if i==len(values) or values[i]!=values[start]:
   yield start,i-1,values[start]
   start=i
scripts=['Greek','Hebrew','Hiragana','Katakana','Han']
script_values=['Other']*0x110000
for line in (base/'17.0.0/Scripts.txt').read_text().splitlines():
 m=re.match(r'([0-9A-F.]+)\s*;\s*(\w+)',line)
 if m and m[2] in scripts:
  span,name=m.groups();start,*end=span.split('..');a=int(start,16);b=int(end[0],16) if end else a
  script_values[a:b+1]=[name]*(b-a+1)
def array(name,data,index):
 result=f'    private static readonly (int First,int Last,byte Value)[] {name} = [\n'
 for a,b,value in data: result+=f'        (0x{a:X},0x{b:X},{index.index(value)}),\n'
 return result+'    ];\n'
text='''// Generated by third_party/unicode-idna/generate.py from Unicode 17.0.0 data.
// Unicode data copyright Unicode, Inc.; Unicode License V3 in third_party/unicode-idna/LICENSE.txt.
namespace WebApi.Infrastructure.Contracts;
internal static class IdnaUnicodeData
{
    internal enum BidiClass {L,R,AL,AN,EN,ES,CS,ET,ON,BN,NSM,Other}
    internal enum ScriptClass {Greek,Hebrew,Hiragana,Katakana,Han,Other}
    internal static BidiClass Bidi(int scalar)=>(BidiClass)Lookup(bidi,scalar);
    internal static ScriptClass Script(int scalar)=>(ScriptClass)Lookup(script,scalar);
    private static byte Lookup((int First,int Last,byte Value)[] ranges,int scalar)
    {
        var low=0;var high=ranges.Length-1;
        while(low<=high){var middle=low+(high-low)/2;var range=ranges[middle];if(scalar<range.First)high=middle-1;else if(scalar>range.Last)low=middle+1;else return range.Value;}
        throw new ArgumentOutOfRangeException(nameof(scalar));
    }
'''
text+=array('bidi',ranges(values),classes)+array('script',ranges(script_values),scripts+['Other'])+'}\n'
out.write_text(text)
files={str(p.relative_to(base)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(base.rglob('*')) if p.is_file() and p.name!='source-manifest.json'}
(base/'source-manifest.json').write_text(json.dumps({'version':'17.0.0','sources':['https://www.unicode.org/Public/17.0.0/ucd/extracted/DerivedBidiClass.txt','https://www.unicode.org/Public/17.0.0/ucd/Scripts.txt','https://www.unicode.org/license.txt'],'files':files,'derived':{'path':str(out.relative_to(repo)),'sha256':hashlib.sha256(out.read_bytes()).hexdigest()}},indent=2)+'\n')
